// 解析 AI 回應結構
const rawOutput = $input.first().json.output || '';
let parsed = {};
try {
  const clean = rawOutput.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = {
    reply: rawOutput,
    intent: '一般產品諮詢',
    escalate_to_human: false,
    summary: 'AI 回覆'
  };
}

const body = $('多渠道客服 Webhook').item.json.body || {};

return [{
  json: {
    ticket_id: 'TKT-' + Date.now(),
    user_id: body.user_id || 'U12345',
    channel: body.channel || '網頁官網',
    user_message: body.message || '',
    ai_reply: parsed.reply,
    intent: parsed.intent,
    escalate_to_human: parsed.escalate_to_human === true,
    summary: parsed.summary,
    timestamp: new Date().toISOString()
  }
}];
